#!/bin/sh
# every suite against PAGE/SERVER (default: the published pair), one line a suite and the full logs in tests/logs/: sh tests/all.sh [prefix]
# SUITES="relay online" picks some; PORT_T is the port of the online ones; the old-server suites need SERVER=<an old server.js> and are not in the list,
# nor are the long ones (soak, transport-battle). The quick ones come first; loadout*, transport, field, world and bases take minutes each
cd "$(dirname "$0")/.." && mkdir -p tests/logs
for t in ${SUITES:-sim-split map-tags tank-capture veiculos-chao hud-labels town-names map-labels rts-commander pack-cut pack-tanks trench-grass gen-cap hangar-short hud-start hud-decimal arma-1p arma-maos hurt tracers hitmarker som sides3-start sides3-online mcp-sides3 relay crew-relay damage-relay drone-relay forts-relay gen-relay resume-relay heli-relay transport-relay sappers-relay pad ana ana-man ana-mano-net g2-regua ana-parado damage heli heli-arms foguete-alcance heli-ai antiaereo-improvisado crew infantry folego pulo squads pop-push mission sem-tickets production smoke-sight perception infantaria-alcance brain-honesty missiles missile-los gbu-lock drone drone-tipos woods forts sappers posts aid city seat cover loadout loadout-more loadout-stores transport field world bases online crew-online drone-online forts-online sappers-online heli-online world-online cover-online bases-online loadout-online transport-online city-online eco-online gen-online resume-online ana-online frame-budget clock sky-relay sky visao-noturna-veiculos sky-online help-relay help pedidos-relay paraquedistas-relay transporte-jogador transporte-jogador-relay pedidos-mapa paraquedistas drills brain brain-lider brain-pelotao brain-falas comms-relay comms radio radio-general logistics-relay logistics logistics-online civ civ-war civ-online rec-relay rec rec-online orders-relay orders orders-online bridges-relay road-mesh ground-mesh bomber-run svbied-cluster bomba-limite bridges bridges-build bridges-online campaign-relay campaign personality-relay personality vet w13 w13-online tmap-relay tmap g2-mundo ambush approaches-relay approaches procedures afp veh-drills brain-drills gfx veg-fade camera-3p sparks-light water-shore road-look rain-wet fire-look smoke-look gunfire-look armas-3p ram fluxos rematch sides3 state-gc}; do
  [ -f tests/$t.js ] || continue
  s=$(date +%s); node tests/$t.js > tests/logs/$1$t.log 2>&1; rc=$?
  echo "$t rc=$rc $(( $(date +%s) - s ))s $(tail -1 tests/logs/$1$t.log)"
done
